  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "description_body",
        "schedule_card",
        "quick_actions_stack",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Global Tech Innovators Summit 2024: SF",
        "variant": "h1"
      },
      "children": []
    },
    "description_body": {
      "type": "Text",
      "props": {
        "text": "This three-day program in San Francisco features keynote addresses from global experts and specialized breakout sessions in AI Ethics, Cloud Scale, and Cybersecurity.",
        "variant": "body"
      },
      "children": []
    },
    "schedule_card": {
      "type": "Card",
      "props": {},
      "children": [
        "schedule_card_content_stack"
      ]
    },
    "schedule_card_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "schedule_header_stack",
        "schedule_image",
        "program_schedule_table"
      ]
    },
    "schedule_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "schedule_icon",
        "schedule_h2"
      ]
    },
    "schedule_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "schedule_h2": {
      "type": "Text",
      "props": {
        "text": "3-Day Program Schedule",
        "variant": "h2"
      },
      "children": []
    },
    "schedule_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Golden_Gate_Bridge_as_seen_from_Baker_Beach.jpg/1200px-Golden_Gate_Bridge_as_seen_from_Baker_Beach.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "program_schedule_table": {
      "type": "Table",
      "props": {
        "statePath": "/programSchedule",
        "columns": [
          {
            "key": "day",
            "label": "Day"
          },
          {
            "key": "date",
            "label": "Date"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "activity",
        "highlightColumns": [
          "time",
          "location"
        ]
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_h2",
        "materials_button",
        "speakers_button"
      ]
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "materials_button": {
      "type": "Button",
      "props": {
        "label": "Access Materials"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://techinnovators-sf.com/materials"
          }
        }
      },
      "children": []
    },
    "speakers_button": {
      "type": "Button",
      "props": {
        "label": "Speaker List"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://techinnovators-sf.com/speakers"
          }
        }
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_h2",
        "agenda_button",
        "sftravel_button"
      ]
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "agenda_button": {
      "type": "Button",
      "props": {
        "label": "Summit Agenda"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://techinnovators-sf.com/schedule"
          }
        }
      },
      "children": []
    },
    "sftravel_button": {
      "type": "Button",
      "props": {
        "label": "SF Travel Events"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.sftravel.com/events"
          }
        }
      },
      "children": []
    }
  }
}
